effect.shader:
#define GM_SAFE_EPSILON 0.0001
float gmSafeDivide(float numerator, float denominator){
float safeDenominator = max(abs(denominator), 0.01);
return numerator / safeDenominator;
}
mat3 gmRotateX(float angle){
float s = sin(angle);
float c = cos(angle);
return mat3(1.0, 0.0, 0.0, 0.0, c, s, 0.0, -s, c);
}
mat3 gmRotateY(float angle){
float s = sin(angle);
float c = cos(angle);
return mat3(c, 0.0, -s, 0.0, 1.0, 0.0, s, 0.0, c);
}
mat3 gmRotateZ(float angle){
float s = sin(angle);
float c = cos(angle);
return mat3(c, s, 0.0, -s, c, 0.0, 0.0, 0.0, 1.0);
}
float gmFountainField(vec2 screen, float timeValue, int stepBudget, int octaveBudget){
vec3 ray = vec3(screen, focalLength);
ray = gmRotateZ(cameraRoll) * gmRotateX(cameraPitch) * gmRotateY(cameraYaw) * ray;
vec3 queryPosition = vec3(cameraX, cameraY, cameraZ);
vec3 position = vec3(0.0);
float stepValue = 0.0;
float radius = 0.0;
float energy = 0.0;
float normalization = max(float(stepBudget) - 0.9, 1.0);
float intensityFrequency = frequencyBase * pow(frequencyGrowth, 6.0);
for(int i = 0; i < 95; i++){
if(i >= stepBudget) break;
float guardedStep = clamp(stepValue, -2.0, 2.0);
queryPosition += ray * guardedStep * radius * stepLength;
queryPosition = clamp(queryPosition, vec3(-10000.0), vec3(10000.0));
position = queryPosition;
radius = length(position) + max(radiusBias, 1.0);
float normalizedDepth = gmSafeDivide(position.z, radius);
position = vec3(
log(max(radius, GM_SAFE_EPSILON)) - timeValue * depthFlow,
exp(-clamp(normalizedDepth, -0.1, 1.4)) + heightOffset,
atan(position.y, position.x) + timeValue * orbitFlow
);
position.y -= surfaceLevel;
stepValue = position.y;
float frequency = frequencyBase;
for(int octave = 0; octave < 6; octave++){
if(octave >= octaveBudget) break;
vec3 waveA = sin(position.zxx * frequency);
vec3 waveB = vec3(1.0) - cos(position.yyz * frequency);
stepValue += gmSafeDivide(dot(waveA, waveB), frequency) * turbulence;
frequency *= frequencyGrowth;
}
energy += clamp(stepValue * intensityFrequency, 0.0, 1.0) / normalization;
}
return clamp(energy, 0.0, 1.5);
}
void main(){
vec2 uv = acScreenNorm;
vec4 source = texture2DCv(inputImg.texture, uv);
float timeValue = evolution;
if(autoAnimate) timeValue += acTime * speed;
vec2 center = vec2(0.5 + centerX * 0.5, 0.5 + centerY * 0.5);
vec2 screen = uv - center;
screen.x *= acScreenSize.x / max(acScreenSize.y, 1.0);
screen *= zoom;
int stepBudget = 48;
int octaveBudget = 4;
if(quality == 1){
stepBudget = 70;
octaveBudget = 5;
}else if(quality == 2){
stepBudget = 95;
octaveBudget = 6;
}
float field = gmFountainField(screen, timeValue, stepBudget, octaveBudget);
field = pow(max(field * intensity, 0.0), contrast);
field = clamp(field, 0.0, 1.0);
vec3 generated = mix(lowColor.rgb, highColor.rgb, field);
float coreMask = smoothstep(0.55, 1.0, field) * hotCore;
generated = mix(generated, hotColor.rgb, coreMask);
if(invert) generated = vec3(1.0) - generated;
vec3 effected = generated;
if(blendMode == 1){
effected = clamp(source.rgb + generated, 0.0, 1.0);
}else if(blendMode == 2){
effected = vec3(1.0) - (vec3(1.0) - source.rgb) * (vec3(1.0) - generated);
}
vec3 outputColor = mix(source.rgb, effected, mixAmount);
float outputAlpha = clipToLayer ? source.a : 1.0;
gl_FragColor = vec4(outputColor * outputAlpha, outputAlpha);
}
